// Fixed level layouts. One string per row, one character per block:
//   '#' wall, ' ' floor, 'S' start, 'X' spike, 'Y' row of spikes right across
//   a corridor, 'D' exit door (in the outer wall), 'G' a space door that slides
//   open and shut by itself (three blocks across a gap; see Maze.js), 'I' a
//   slippery spot on the floor (a strip right across a corridor), 'O' a gap
//   with no floor, crossed on a moving platform (Level 17 on), 'Z' a second
//   spike on the path with its own size (spike2Radius), 'F' a gap like 'O'
//   whose leaf goes about 30% faster (Level 27), 'W' a water current (Level
//   41: fills a whole corridor cell; walking in from the path shoves you to
//   the 'V', the middle of the side dead end's first cell). Candy World
//   (Level 52 on): 'O' is a chocolate river with a bouncy marshmallow on
//   each bank, and 'C' is sticky caramel (a whole corridor cell, half speed)
//   Robot Factory World (Level 82 on): 'B' a backward belt and 'L' where it
//   flings you (the middle of the first cell of its hallway); beltQuiet sets
//   how long it stays off and quiet before its warning (see Maze.js)
//   Desert Pyramid World (Level 101 on): 'J' a button door (three blocks
//   across the wall gap between two path cells, solid until its button is
//   pressed) and 'U' its button (the middle of a wrong way's last cell)
//   (a second button door in the same level: 'j' and its button 'u')
// Found with tools/find-level.mjs. theme: colors and the fluffy look, see Maze.js.
// music: the level's tune (see sound.js), a little sneakier each level.
// spikeRadius: size of the spike's plate (default 0.75; see Maze.js).
// spike2Radius: the second path spike's ('Z') plate, Level 20's tighter squeeze.
// finale: the last level of a world: golden door, confetti, its own end title.

// Levels 1-10 share the cotton candy look: fluffy pink walls on blue ground.
const COTTON_CANDY = { wall: 0xff9fcf, floor: 0x6fb8ff, sky: 0xe6d6ff, fluffy: true };
// Levels 11-20, Space World: star walls, metal floor, a dark sky with Earth,
// the Moon and things flying by (see Maze.js)
const SPACE = { wall: 0x1c2153, floor: 0x8c939c, sky: 0x04060f, space: true };
// Levels 21-30, Jungle World: thick green leaf-and-vine walls, a brown dirt
// path, a bright sky with parrots, toucans and butterflies (see Maze.js)
const JUNGLE = { wall: 0x2e7d32, floor: 0x8b5a2b, sky: 0x9fdcff, jungle: true };
// Levels 31-40, Moon World: a secret high-tech base on the Moon. Shiny metal
// walls with security cameras, gray moon dust with footprints, a black starry
// sky with the Earth; the spikes are craters (see Maze.js)
const MOON = { wall: 0xb6bfca, floor: 0x9a9a9c, sky: 0x000000, moon: true };
// Levels 41-50, Underwater World: colorful coral reef walls, soft white sand
// with seashells and starfish, open water above with turtles, whales, manta
// rays and schools of little fish; the spikes are sea urchins (see Maze.js)
const UNDERWATER = { wall: 0xff7f6e, floor: 0xf2e6c9, sky: 0x1f8fc4, underwater: true };
// Levels 51-60, Candy World: walls of giant stacked gumdrops, a floor of
// chocolate bar squares, a sky of cotton candy clouds and balloons; the spikes
// are pointy broken candy canes (see Maze.js)
const CANDY = { wall: 0xff5fa2, floor: 0x5b3320, sky: 0xa9dcff, sweets: true };
// Levels 61-70, Volcano World: walls of shiny black volcano rock with glowing
// orange cracks, a floor of black swirly cooled lava, a dark red sky with ash
// falling like snowflakes; the spikes are giant glowing hot coals (see Maze.js)
const VOLCANO = { wall: 0x0d0b0c, floor: 0x141012, sky: 0x4a0d08, volcano: true };
// Levels 71-80, Ice World: walls of frosty blue ice blocks that glow but
// can't be seen through, crunchy snow with little ice patches (just for
// looks), a night sky with green and purple northern lights, snowy owls and
// falling snow; the spikes are icicles hanging from igloo arches (see Maze.js)
const ICE = { wall: 0x6fb6f0, floor: 0xeef4fb, sky: 0x0a1633, ice: true };
// Levels 81-90, Robot Factory World: walls of rusty orange metal with pipes
// and little puffs of steam, a floor of crisscross metal grating with dark
// machines whirring far below, no ceiling, and a sky of giant gears turning
// slowly up high; the spikes are electric zappers (see Maze.js)
const FACTORY = { wall: 0xb5582a, floor: 0x5a6067, sky: 0x56606e, factory: true };
// Levels 101-110, Desert Pyramid World: walls of big sandy-yellow stone
// blocks carved with pictures like ancient Egyptian writing, a floor of
// golden sand with little wavy ripples, a bright blue sky with a hot sun and
// pyramids and camels far away; the spikes are prickly cactuses (see Maze.js)
const DESERT = { wall: 0xd9b46a, floor: 0xe8bf6a, sky: 0x5fb4ff, desert: true };
// Levels 111-120, Dinosaur World: walls of giant ferns and big rocks, a dirt
// floor with huge dinosaur footprints pressed into it, a sky with friendly
// pterodactyls gliding by; the spikes are pointy fossil bones, and the gaps
// are pits crossed on a long-neck dinosaur's head (see Maze.js). The baby
// triceratops buddy comes along in every level (see Buddy.js).
const DINO = { wall: 0x3f7a2c, floor: 0x8f6a44, sky: 0x8fd3ff, dino: true };
// Levels 121-130, Pirate Ship World: a wooden deck floor, walls of stacked
// crates and barrels with the ship's rail along the top, big sails, masts
// and seagulls in the sky and the sea all round, far below; the spikes are
// broken planks with pointy splinters, and the water gaps are holes in the
// deck down to the sea, crossed by cannon (see Maze.js). No pirates.
const PIRATE = { wall: 0x8a5a2b, floor: 0xb07a45, sky: 0x8fd3ff, pirate: true };
// Levels 131-140, Sky World: a floating island high in the sky, walls of
// mossy stone, a grassy floor, clouds drifting far below (seen past the
// island's edges and down every gap), birds and kites flying by; the spikes
// are little storm clouds with lightning bolts poking down, and the gaps
// are crossed on rainbow bridges that come and go (see Maze.js).
const SKY = { wall: 0x8a8f96, floor: 0x5fae3e, sky: 0x7cc8ff, skyland: true };

